// formatDistance turns a distance in kilometres into display data:
// formatDistance(5)    gives { km: 5, label: "5 km" }
// formatDistance(11.5) gives { km: 11.5, label: "11.5 km" }
export function formatDistance(km) {
  return { km, label: `${km} km` };
}
